{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL injection vulnerability",
      "severity": "High",
      "file": "AccountSearchController.cls",
      "lines": "4",
      "explanation": "The Apex class constructs a SOQL query by concatenating user input directly into the query string without using bind variables. This makes it vulnerable to SOQL injection attacks where malicious input could manipulate the query to access unauthorized data.",
      "remediation": "Replace the dynamic query construction with a static SOQL query using bind variables like 'SELECT Id, Name, Industry FROM Account WHERE Name LIKE :searchKey LIMIT 50'."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOSL Injection",
      "severity": "High",
      "file": "InvoiceSearchController.cls",
      "lines": "searchInvoices method",
      "explanation": "The invoiceNum parameter is concatenated directly into the SOSL search term without sanitization. This allows an attacker to inject malicious SOSL syntax and potentially access unauthorized data. The concatenation occurs on line where searchTerm is built.",
      "remediation": "Use bind variables for user input in SOSL queries. Replace 'Invoice-' + invoiceNum with a properly bound variable like ':invoiceNum' or escape the input using String.escapeSingleQuotes before concatenation."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection via Dynamic Query Construction",
      "severity": "High",
      "file": "ReportFilterController.cls",
      "lines": "7-15",
      "explanation": "The code concatenates user-provided filter strings directly into a SOQL query without any validation or escaping. This allows an attacker to inject malicious SOQL syntax, potentially leading to unauthorized data access or manipulation.",
      "remediation": "Validate and sanitize the field names and values in fieldFilters against a predefined allow-list. Use bind variables for values and ensure field names are validated before inclusion in the query."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "CRUD/FLS violation in OpportunityStageService",
      "severity": "High",
      "file": "OpportunityStageService.cls",
      "lines": "7",
      "explanation": "The class uses WITH USER_MODE in the SOQL query but does not enforce field-level security. The Opportunity.StageName field is editable in the permission set, but the code updates this field without checking if the user has sufficient permissions to modify it. Additionally, the Amount field is readable but not editable in the permission set, yet the code retrieves it.",
      "remediation": "Use Security.stripInaccessible() after the SOQL query to enforce field-level security and ensure only accessible fields are returned. Also, verify that the user has appropriate CRUD permissions before attempting to update the StageName field."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "CRUD violation in ContractAmendmentService",
      "severity": "High",
      "file": "ContractAmendmentService.cls",
      "lines": "amendContract method",
      "explanation": "The amendContract method uses 'update as user' which bypasses CRUD checks. This allows users to update contracts even if they don't have edit permissions on the Contract object, potentially leading to unauthorized data modification.",
      "remediation": "Remove 'as user' from the update statement and use Security.stripInaccessible before updating, or enforce CRUD checks using WITH USER_MODE in SOQL queries."
    },
    {
      "category": "C4",
      "title": "Excessive permissions in Contract Amendment Editor permission set",
      "severity": "Medium",
      "file": "Contract_Amendment_Editor.permissionset-meta.xml",
      "lines": "classAccesses section",
      "explanation": "The permission set grants access to the ContractAmendmentService class, which is an Aura-enabled service. This allows any guest user or authenticated user with this permission set to call the service methods, potentially exposing contract data and functionality.",
      "remediation": "Review the permission set's class access and ensure it's only granted to users who need it. Consider restricting access to specific profiles or roles that require this functionality."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "CRUD violation in AssetRetirementService",
      "severity": "High",
      "file": "AssetRetirementService.cls",
      "lines": "retireAsset method",
      "explanation": "The AssetRetirementService class uses WITH USER_MODE in the SOQL query, but it does not enforce field-level security (FLS) or check if the user has sufficient permissions to delete the asset. The code assumes that if the object is deletable, the user can delete any asset, which may not be true for all users.",
      "remediation": "Use Security.stripInaccessible() after the SOQL query to ensure field-level security is enforced and check that the user has proper CRUD permissions before attempting deletion. Also, verify that the user has the necessary object permissions through the permission set."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "CRUD/FLS violations",
      "severity": "Medium",
      "file": "ContactPhoneService.cls",
      "lines": "4",
      "explanation": "The Apex class does not enforce CRUD/FLS checks. It directly queries and updates a Contact record without verifying if the user has appropriate permissions to read or modify the Phone field. This can lead to data exposure or modification beyond user permissions.",
      "remediation": "Add WITH USER_MODE to the SOQL query and use Security.stripInaccessible() after querying to ensure that only accessible fields are returned and that CRUD/FLS are enforced."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "CRUD/FLS violations",
      "severity": "High",
      "file": "AccountRatingService.cls",
      "lines": "Account acc = [SELECT Id, AnnualRevenue, Rating FROM Account WHERE Id = :accountId];",
      "explanation": "The code queries the Account object in system mode without enforcing CRUD/FLS checks. It reads AnnualRevenue and updates Rating without verifying if the user has permission to access these fields or modify the record. This can lead to data exposure or modification beyond user permissions.",
      "remediation": "Add WITH USER_MODE to the SOQL query and use Security.stripInaccessible() after querying to ensure field-level security is enforced. Also, explicitly check field permissions before updating."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "FLS violation in Task creation",
      "severity": "High",
      "file": "CaseEscalationService.cls",
      "lines": "13-19",
      "explanation": "The code attempts to create a Task without checking if the user has permission to create Tasks. The DmlException is silently caught, hiding potential FLS violations from the caller. Even though the permission set doesn't grant Task creation rights, the service still tries to insert a Task.",
      "remediation": "Add a check for Task object permissions using Security.isCreateable() before attempting to insert the Task, or ensure the permission set grants appropriate Task creation permissions."
    },
    {
      "category": "C4",
      "title": "Excessive permissions in permission set",
      "severity": "Medium",
      "file": "Case_Escalation_Agent.permissionset-meta.xml",
      "lines": "10-11",
      "explanation": "The permission set grants access to the CaseEscalationService class but does not grant explicit Task creation permissions. However, the service logic attempts to create Tasks without checking if the user has such permissions, which could lead to privilege escalation or data exposure.",
      "remediation": "Either remove access to the CaseEscalationService class from users who don't need to create Tasks, or ensure that the service properly enforces FLS checks before attempting to create Tasks."
    }
  ]
}

