    {
      "category": "C3",
      "title": "Missing sharing enforcement",
      "severity": "High",
      "file": "CaseHistoryController.cls",
      "lines": "1",
      "explanation": "The class is declared 'without sharing', which means it ignores record-level sharing settings. This allows users to potentially access Case records they shouldn't be able to see based on their sharing rules or roles.",
      "remediation": "Change the class declaration from 'without sharing' to 'with sharing' or 'inherited sharing' to enforce proper record-level security."
    },
    {
      "category": "C2",
      "title": "Missing CRUD/FLS enforcement",
      "severity": "Medium",
      "file": "CaseHistoryController.cls",
      "lines": "10",
      "explanation": "While the code uses Security.stripInaccessible, it doesn't enforce CRUD/FLS at the SOQL level. This could allow users with read access to Case object but not specific fields to potentially see unauthorized field data.",
      "remediation": "Use WITH USER_MODE in SOQL queries or explicitly check field permissions using Schema.FieldPermissions before querying."
    }
  ]
}

